125	#[derive(Debug, PartialEq, Eq, Clone)]
126	enum ParseState<'a> {
127	    /// Parsing a value done, there is no state to record.
128	    ValueDone,
129	
130	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
131	    Pos((usize, usize)),
132	
133	    /// Parsing a optional flag argument
134	    Opt((&'a clap::Arg, usize)),
135	}
